package com.supersec.pedidos.controller; import com.supersec.pedidos.dto.OrderRequest; import com.supersec.pedidos.model.Order; import com.supersec.pedidos.service.OrderService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/orders") public class OrderController {private final OrderService s;public OrderController(OrderService s){this.s=s;} @PostMapping public Order create(@Valid @RequestBody OrderRequest x,Authentication a){return s.create(a.getName(),x);} @GetMapping("/mine") public List<Order> mine(Authentication a){return s.mine(a.getName());}}
